#!/usr/bin/env python3
"""Refresh and validate docs/insights index and links."""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path


def _repo_root() -> Path:
    return Path(__file__).resolve().parents[1]


def _collect_insight_files(insights_dir: Path) -> list[Path]:
    return sorted(
        [p for p in insights_dir.glob("*.md") if p.name != "INDEX.md"],
        key=lambda p: p.name.lower(),
    )


def _generate_index_lines(files: list[Path]) -> list[str]:
    lines = [
        "# Insights index",
        "",
        "Auto-generated by scripts/refresh_insights.py.",
        "",
        "Files:",
        "",
    ]
    for path in files:
        lines.append(f"- {path.name}")
    return lines


def _read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def _write_text(path: Path, text: str) -> None:
    path.write_text(text, encoding="utf-8")


def _extract_insights_links(text: str) -> list[str]:
    pattern = re.compile(r"`docs/insights/([^`]+)`")
    return pattern.findall(text)


def _collect_referenced_graph(insights_dir: Path, insights_md: Path) -> tuple[set[str], list[str]]:
    """Follow docs/insights links transitively from docs/INSIGHTS.md."""
    if not insights_md.exists():
        return set(), [str(insights_md)]

    referenced: set[str] = set()
    missing: list[str] = []
    queue: list[Path] = [insights_md]
    visited: set[Path] = set()

    while queue:
        current = queue.pop(0)
        if current in visited or not current.exists():
            continue
        visited.add(current)
        for rel in _extract_insights_links(_read_text(current)):
            referenced.add(rel)
            target = insights_dir / rel
            if not target.exists():
                missing.append(str(target))
                continue
            # Recurse only into markdown docs under docs/insights.
            # Legacy full snapshots are treated as read-only archives and are not scanned transitively.
            if target.suffix.lower() == ".md" and not target.name.startswith("INSIGHTS_legacy_"):
                queue.append(target)
    return referenced, sorted(set(missing))


def _orphan_files(insights_dir: Path, referenced: set[str]) -> list[str]:
    orphans: list[str] = []
    for path in _collect_insight_files(insights_dir):
        if path.name not in referenced:
            orphans.append(path.name)
    return sorted(orphans)


def main() -> int:
    parser = argparse.ArgumentParser(description="Refresh insights index and validate links.")
    parser.add_argument("--check", action="store_true", help="Only check; do not write files.")
    args = parser.parse_args()

    root = _repo_root()
    insights_dir = root / "docs" / "insights"
    index_path = insights_dir / "INDEX.md"
    insights_md = root / "docs" / "INSIGHTS.md"

    if not insights_dir.exists():
        print(f"Missing insights directory: {insights_dir}")
        return 2

    files = _collect_insight_files(insights_dir)
    index_lines = _generate_index_lines(files)
    index_text = "\n".join(index_lines) + "\n"

    referenced, missing = _collect_referenced_graph(insights_dir, insights_md)
    if missing:
        print("Missing insight files referenced from INSIGHTS graph:")
        for path in missing:
            print(f"- {path}")
        return 3

    orphans = _orphan_files(insights_dir, referenced)
    if orphans:
        print("Orphaned insight files (not referenced from INSIGHTS graph):")
        for name in orphans:
            print(f"- {name}")

    if args.check:
        if not index_path.exists():
            print(f"Missing index file: {index_path}")
            return 4
        current = _read_text(index_path)
        if current != index_text:
            print("Index is stale. Run: python3 scripts/refresh_insights.py")
            return 5
        print("OK: index up to date and links valid.")
        return 0

    _write_text(index_path, index_text)
    print(f"Wrote index: {index_path}")
    if orphans:
        print("Note: some insight files are not referenced in INSIGHTS graph.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
